{
  "criteria": [
    {
      "id": "C1",
      "level": "Adequate",
      "mark": 6,
      "evidence": [
        {
          "where": "Mission Concept & Rationale",
          "quote": "A near-real-time relay to monitoring stations on the ground would allow marine and conservation scientists to more accurately predict and react to coral bleaching events."
        },
        {
          "where": "Mission Concept & Rationale",
          "quote": "This tool could be applied to a new satellite over the Great Barrier Reef."
        }
      ],
      "reasoning": "The report establishes a relevant Australian need, identifies marine and conservation scientists as users, and explains the intended monitoring benefit. However, the mission remains broad: it lacks defined objectives and requirements such as sensor capability, coverage, revisit time, or data-delivery performance."
    },
    {
      "id": "C2",
      "level": "Adequate",
      "mark": 6,
      "evidence": [
        {
          "where": "Image 1",
          "quote": ""
        },
        {
          "where": "Project Plan & Preliminary Progress",
          "quote": "The goal is to brainstorm and research as many possible strategies for the satellite’s launch/orbit and then gradually cut and refine them over the next few weeks"
        }
      ],
      "reasoning": "The Gantt chart provides a timetable and the task descriptions cover research, launch, orbit, ground control, communications, end of life, STK work, and editing. Planned sources are listed separately. The plan lacks contingency provision and some tasks and milestones remain quite general."
    },
    {
      "id": "C3",
      "level": "Adequate",
      "mark": 4,
      "evidence": [
        {
          "where": "Project Plan & Preliminary Progress",
          "quote": "completed STK tutorials 1, 2, 3 & 4."
        }
      ],
      "reasoning": "Background research and software tutorials are useful initial progress, but the submission contains no preliminary calculations, orbit or launch selection, payload analysis, or STK results. Technical progress is therefore limited and not yet demonstrated through design results."
    },
    {
      "id": "C4",
      "level": "Adequate",
      "mark": 6,
      "evidence": [
        {
          "where": "Image 1",
          "quote": ""
        },
        {
          "where": "Useful Links",
          "quote": "https://coralreefwatch.noaa.gov/satellite/publications/nim_skirving_reef_vulnerability.pdf"
        }
      ],
      "reasoning": "The report is logically divided by headings and the Gantt chart is labelled and readable. The prose is generally understandable, though some phrasing is awkward, and references are presented largely as bare URLs rather than complete, consistently formatted citations."
    }
  ],
